def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: Mapping of resource identifiers to their generated observer schemas.
    """
    # Validate 'app' and 'spec.manifest'
    try:
        spec = getattr(app, 'spec', None)
        if spec is None:
            raise AttributeError("Application has no 'spec' attribute.")
        manifest = getattr(spec, 'manifest', None)
    except Exception as exc:
        raise ValueError(f"Invalid application object: {exc}")

    # If no manifest, return empty mapping
    if not manifest:
        return {}

    # Ensure manifest is iterable
    if isinstance(manifest, dict):
        # Single resource case
        manifest_iter = [manifest]
    else:
        try:
            manifest_iter = list(manifest)
        except TypeError:
            # Not iterable, can't proceed
            raise ValueError("Application.spec.manifest must be a list or dict of resources.")

    default_schemas = {}

    for res in manifest_iter:
        if not isinstance(res, dict):
            continue  # skip invalid entries

        # Determine if a custom observer schema already exists
        # Users may specify it under different keys, check a few common ones
        has_custom = any(
            res.get(key) is not None
            for key in ('observerSchema', 'customObserverSchema', 'krakeObserverSchema')
        )
        if has_custom:
            continue

        # Build a unique key for this resource
        kind = res.get('kind', 'Unknown')
        name = res.get('metadata', {}).get('name', 'Unnamed')

        identifier = f"{kind}_{name}"

        # Generate a very simple default schema that mirrors the resource structure
        # without throwing errors if expected fields are missing.
        schema = {
            "type": "object",
            "properties": {
                "kind": {"type": "string", "default": kind},
                "apiVersion": {"type": "string", "default": res.get("apiVersion", "")},
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string", "default": name}
                    }
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["kind", "metadata"]
        }

        default_schemas[identifier] = schema

    return default_schemas
